url = "https://imagecolorpicker.com/color-code/c69676?skipGenerate=true"
try:
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    html = urllib.request.urlopen(req, timeout=15).read().decode("utf-8", "replace")
    print("LEN:", len(html))
    # print title and some meta
    import re
    for m in re.findall(r"<title>(.*?)</title>", html)[:5]:
        print("TITLE:", m)
    # find og:description or meta descriptions
    for m in re.findall(r'<meta[^>]*name=["\'](?:description|og:description)[^>]*content=["\'](.*?)["\']', html)[:5]:
        print("DESC:", m)
except Exception as e:
    print("ERR:", type(e).__name__, e)
"}

