{"code": "import math
def srgb_to_linear(c):
    return c/12.92 if c <= 0.04045 else ((c+0.055)/1.055)**2.4
def lum(hexv):
    hexv = hexv.lstrip("#")
    r,g,b = int(hexv[0:2],16)/255, int(hexv[2:4],16)/255, int(hexv[4:6],16)/255
    return 0.2126*srgb_to_linear(r)+0.7152*srgb_to_linear(g)+0.0722*srgb_to_linear(b)
def contrast(h1,h2):
    l1,l2 = lum(h1), lum(h2)
    if l1 < l2: l1,l2 = l2,l1
    return (l1+0.05)/(l2+0.05)
# text color probably white #fff or black #000 on bg #c69676
print("black text on c69676:", round(contrast("000000","c69676"),2))
print("white text on c69676:", round(contrast("ffffff","c69676"),2))
"}
